import React, { useContext, useEffect, useState } from "react";
import {
  Button,
  Card,
  CardContent,
  Divider,
  Grid,
  IconButton,
  Paper,
  Typography,
} from "@mui/material";
import { Box, useTheme } from "@mui/system";
import CheckOutlinedIcon from "@mui/icons-material/CheckOutlined";
import TableBarOutlinedIcon from "@mui/icons-material/TableBarOutlined";
import ChairAltOutlinedIcon from "@mui/icons-material/ChairAltOutlined";
import { QRCodeSVG } from "qrcode.react";
import axios from "axios";
import { toast } from "react-toastify";
import AddTableModal from "./AddTable"; // Ensure this component is created
import styles from "../SupportClient/supportCard.module.css";
import { useTranslation } from "react-i18next";
import { BASE_URL, BASE_URL_IMG } from "../../../../utils/constants";
import { useDispatch, useSelector } from "react-redux";
import {
  createTable,
  deleteTable,
  fetchAreaData,
  fetchTablesData,
  selectBranch,
  selectSelectedBranch,
  selectTablesData,
  updateTable,
} from "../../../../store/client/clientAdmin";
import { useGetTablesByBranchID } from "../../../../Hooks/Queries/clientDashBoard/tables/useGetTablesByBranchID";

const TableCard = ({ table, onDeleteTable, onEditTable }) => {
  const { t } = useTranslation();
  const theme = useTheme();
  const handleCopyLink = (qrLink) => {
    const link = `${qrLink}`;
    navigator.clipboard
      .writeText(link)
      .then(() => alert(t("linkCopied")))
      .catch((error) => alert(t("faildToCopyLink"), error));
  };

  return (
    <Card
      className={styles.card3} // Apply the card3 class for the gradient background
      sx={{
        height: "270px",
        maxWidth: 180,
        width: "140px",
        borderRadius: "10px",
        backgroundColor: "rgb(211, 221, 253)", // Base background color for the card
        position: "relative",
      }}
    >
      <CardContent
        sx={{
          zIndex: 5, // Ensure content is above the ::before pseudo-element
          height: "100%", // Ensure the background covers the entire content area
          position: "relative", // Ensure the content is positioned correctly
        }}
      >
        <Box display={"flex"} justifyContent={"space-between"}>
          <Typography
            variant="subtitle2"
            sx={{ fontSize: "11px", color: theme.palette.orangePrimary.main }}
          >
            {t("id")}{" "}
            <span
              style={{
                fontSize: "10px",
                color: "#AAAAAA",
                borderBottom: "1px solid #AAAAAA",
              }}
            >
              {table?.id}
            </span>
          </Typography>
          <span
            onClick={onDeleteTable}
            className="icon-delete"
            style={{ fontSize: "15px", color: "red", cursor: "pointer" }}
          />
        </Box>
        <Divider
          sx={{
            backgroundImage: "linear-gradient(to right, #FDB913, #F2672E)",
            height: "2px",
            marginTop: "2px",
            border: "none",
          }}
        />

        <Typography
          sx={{
            fontSize: "12px",
            display: "flex",
            color: "#7b6a6a",
            marginTop: "9px",
          }}
        >
          <TableBarOutlinedIcon sx={{ fontSize: "12px", mr: "5px" }} /> Name
        </Typography>
        <Typography
          variant="body2"
          component="div"
          sx={{
            fontSize: "9px",
            display: "flex",
            color: "#9d9d9c",
            marginLeft: "5px",
          }}
        >
          {table?.name}
        </Typography>

        <Box display={"flex"} justifyContent={"space-between"}>
          <Box>
            <Typography
              variant="body2"
              sx={{
                fontSize: "10px",
                display: "flex",
                color: "#7b6a6a",
                marginTop: "10px",
              }}
            >
              <ChairAltOutlinedIcon sx={{ fontSize: "14px", mr: "5px" }} />
              Chair
            </Typography>
            <Typography
              variant="body2"
              sx={{
                fontSize: "10px",
                display: "flex",
                color: "#9d9d9c",
                marginLeft: "5px",
              }}
            >
              {table?.table_number} ch
            </Typography>
          </Box>
          <Box>
            <Typography
              variant="body2"
              sx={{
                fontSize: "10px",
                display: "flex",
                color: "#7b6a6a",
                marginTop: "10px",
              }}
            >
              <img
                src="/assets/location.svg"
                alt="location icon"
                style={{ width: "13px", height: "13px" }}
              />
              Area
            </Typography>
            <Typography
              variant="body2"
              sx={{
                fontSize: "10px",
                display: "flex",
                color: "#9d9d9c",
                marginLeft: "10px",
              }}
            >
              {table.area}
            </Typography>
          </Box>
        </Box>

        <Box
          sx={{
            height: "100px",
            textAlign: "center",
            borderRadius: "10px",
            border: "3px solid #ef7d00",
            margin: "10px auto",
            display: "flex",
            width: "90%",
            padding: "2px 5px",
            justifyContent: "center",
            alignContent: "center",
          }}
        >
          <QRCodeSVG
            value={`${table?.link}`}
            size={90}
            fgColor="#000000"
            bgColor="#FFFFFF"
            level="Q"
          />
        </Box>

        <Grid container justifyContent="center" alignItems="center">
          <IconButton onClick={() => handleCopyLink(table?.link)}>
            <span
              className="icon-link"
              style={{ fontSize: "15px", color: "black" }}
            />
          </IconButton>
          <IconButton>
            <span
              className="icon-qr-code"
              style={{ fontSize: "15px", color: "black" }}
            />
          </IconButton>
          <IconButton onClick={() => onEditTable(table)}>
            <span
              className="icon-edit"
              style={{ fontSize: "18px", color: "black" }}
            />
          </IconButton>
        </Grid>
      </CardContent>
    </Card>
  );
};
export const Tables = ({ openOldMenu }) => {
  const theme = useTheme();
  const { t } = useTranslation();
  const dispatch = useDispatch();

  const [modalOpen, setModalOpen] = useState(false);
  const [editingTable, setEditingTable] = useState(null);

  const handleOpenModal = () => {
    setModalOpen(true);
  };

  const handleCloseModal = () => {
    setModalOpen(false);
    setEditingTable(null); // Reset editing table state
  };

  const handleEditTable = (table) => {
    setEditingTable(table);
    setModalOpen(true);
  };

  const handleDeleteTable = async (id) => {
    try {
      const response = await axios.delete(`${BASE_URL}tables/${id}`, {
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${localStorage.getItem("Token")}`,
        },
      });

      if (response.data) {
        toast.success(t("table.deleteSucc"));
        dispatch(deleteTable(id));
      }
    } catch (error) {
      console.error("Error deleting table:", error);
      toast.error(t("table.deleteErr"));
    }
  };

  const data = useSelector(selectSelectedBranch);
  const { data: tables } = useGetTablesByBranchID(data);
